import type { AlienPreset } from "./types";
import { subtypeTag, withinTag } from "./types";

/**
 * Charted space, checked against the book: the regions of known space
 * (p. 112), Systems & Planets (chapter 9, p. 180-201, with the summary table
 * on p. 181), the Tartarus Sector campaign setting (p. 260-268), Jackson's
 * Star (p. 269-273), Novgorod Station (p. 274-277) and Anchorpoint Station
 * (p. 113). Placement follows the star maps (PDF pages 2-3, p. 262).
 *
 * Containment is expressed with `within:<presetId>` tags; the importer turns
 * them into `within` relationships. Political blocs use the `region` subtype
 * with a `bloc` tag because the field doc has no bloc subtype.
 *
 * Stat blocks are data: `locationNote`, `affiliation`, `classification`,
 * `climate`, `temperature`, `terrain`, `coloniesNote`, `population` and
 * `keyResources` (chapter 9) or `resources` (chapter 11) copy the book's
 * values. Descriptions are short paraphrases. `page` is the main entry;
 * `alsoPages` lists a second chapter that covers the same place.
 *
 * Module decisions (not printed in the book, documented here):
 * - `allegiance` maps the affiliation line onto the field-doc ids.
 * - `colonySize` is derived from a numeric population using the colony size
 *   ranges on p. 240 (under 300 start-up, under 2,000 young, else established);
 *   colonies without a usable population have none.
 * - `missions` use the colony mission labels of p. 241 where the text states
 *   what the colony does; otherwise the list is empty.
 * - The book gives no spectral or brightness classes for these systems, so
 *   star systems carry `starNote` (the book's own wording, e.g. "Binary")
 *   instead of `starClass`/`brightness`.
 * - The Far Reach is a region in the overview (p. 112) and a Frontier sector in
 *   the chapter 9 table (p. 181); it is kept as a region placed within the Frontier.
 * - Anchorpoint Station's system GJ2066 is drawn on the Tartarus sector map
 *   (p. 262); the text puts the station just past the sector's rimward edge
 *   (p. 260). It is placed within the sector here.
 */

type Subtype = "region" | "sector" | "star-system" | "planet" | "colony" | "site";

interface LocationSpec {
  id: string;
  subtype: Subtype;
  name: string;
  summary: string;
  page: number | [number, number];
  within?: string;
  fields: Record<string, unknown>;
  tags?: string[];
}

const PREFIX = "alien.location.";

function location(spec: LocationSpec): AlienPreset {
  const tags = ["location", subtypeTag(spec.subtype), ...(spec.tags ?? [])];
  if (spec.within) tags.push(withinTag(`${PREFIX}${spec.within}`));
  return {
    id: `${PREFIX}${spec.id}`,
    entityType: "alien.location",
    subtype: spec.subtype,
    name: spec.name,
    summary: spec.summary,
    page: spec.page,
    tags,
    fields: spec.fields,
  };
}

/** Colony size from a numeric population (p. 240 ranges, module decision). */
function sizeOf(population: unknown): { colonySize?: string } {
  if (typeof population !== "number") return {};
  if (population < 300) return { colonySize: "start-up" };
  if (population < 2000) return { colonySize: "young" };
  return { colonySize: "established" };
}

const FACTION_TYPES: Record<string, string> = {
  "United Americas": "government",
  "Three World Empire": "government",
  UPP: "government",
  "Independent Core System Colonies": "government",
  "Central Space Consortium": "government",
  "Colonial Administration": "government",
  USCMC: "military",
  ORDF: "military",
  "UA security": "military",
  "Weyland-Yutani": "corporation",
  Seegson: "corporation",
  "Lasalle Bionational": "corporation",
  "Lunnar-Welsun": "corporation",
  "Alphatech Corp.": "corporation",
};

interface ColonyFields {
  population?: number | string;
  allegiance: string;
  affiliation?: string;
  /** Affiliated parties; becomes `factions` with a type looked up above. */
  parties?: string[];
  missions?: string[];
  classification?: string;
  resources?: string;
  campaignHook?: string;
  description: string;
  [extra: string]: unknown;
}

function colonyFields(f: ColonyFields): Record<string, unknown> {
  const { parties, missions, ...rest } = f;
  return {
    ...sizeOf(f.population),
    missions: missions ?? [],
    factions: (parties ?? []).map((name) => ({ type: FACTION_TYPES[name] ?? "other", name })),
    ...rest,
  };
}

